import { MakeLogicType, afterMount, connect, kea, key, path, props, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { ApiConfig } from 'lib/api'
import { FEATURE_FLAGS } from 'lib/constants'
import { FeatureFlagsSet, featureFlagLogic } from 'lib/logic/featureFlagLogic'

import { workflowImportsForWorkflowRetrieve } from 'products/workflows/frontend/generated/api'
import { WorkflowImportNoteApi, WorkflowImportRecordApi } from 'products/workflows/frontend/generated/api.schemas'

export interface WorkflowImportNotesLogicProps {
    id: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowImportNotesLogicValues {
    featureFlags: FeatureFlagsSet // featureFlagLogic
    importRecord: WorkflowImportRecordApi | null
    importRecordLoading: boolean
    loadFailed: boolean
    notesByStepId: Record<string, WorkflowImportNoteApi[]>
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowImportNotesLogicActions {
    loadImportRecord: () => any
    loadImportRecordFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadImportRecordSuccess: (
        importRecord: WorkflowImportRecordApi | null,
        payload?: any
    ) => {
        importRecord: WorkflowImportRecordApi | null
        payload?: any
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface workflowImportNotesLogicMeta {
    key: string
    __keaTypeGenInternalSelectorTypes: {
        notesByStepId: (importRecord: WorkflowImportRecordApi | null) => Record<string, WorkflowImportNoteApi[]>
    }
}

export type workflowImportNotesLogicType = MakeLogicType<
    workflowImportNotesLogicValues,
    workflowImportNotesLogicActions,
    WorkflowImportNotesLogicProps,
    workflowImportNotesLogicMeta
>

export const workflowImportNotesLogic = kea<workflowImportNotesLogicType>([
    path((key) => ['products', 'workflows', 'frontend', 'Workflows', 'import', 'workflowImportNotesLogic', key]),
    props({} as WorkflowImportNotesLogicProps),
    key((props) => props.id),
    connect(() => ({ values: [featureFlagLogic, ['featureFlags']] })),
    loaders(({ props }) => ({
        importRecord: [
            null as WorkflowImportRecordApi | null,
            {
                loadImportRecord: async () => {
                    try {
                        return await workflowImportsForWorkflowRetrieve(String(ApiConfig.getCurrentTeamId()), {
                            hog_flow_id: props.id,
                        })
                    } catch (error: any) {
                        // Most workflows were never imported, which the endpoint answers with a 404.
                        if (error?.status === 404) {
                            return null
                        }
                        throw error
                    }
                },
            },
        ],
    })),
    reducers({
        loadFailed: [
            false,
            {
                loadImportRecord: () => false,
                loadImportRecordFailure: () => true,
            },
        ],
    }),
    selectors({
        notesByStepId: [
            (s) => [s.importRecord],
            (importRecord: WorkflowImportRecordApi | null): Record<string, WorkflowImportNoteApi[]> => {
                const byStep: Record<string, WorkflowImportNoteApi[]> = {}
                for (const note of importRecord?.notes ?? []) {
                    if (note.step_id) {
                        byStep[note.step_id] = [...(byStep[note.step_id] ?? []), note]
                    }
                }
                return byStep
            },
        ],
    }),
    afterMount(({ actions, props, values }) => {
        // Only teams with the import can have imported workflows, so nobody else asks and gets a 404.
        if (props.id && props.id !== 'new' && values.featureFlags[FEATURE_FLAGS.WORKFLOWS_CUSTOMERIO_IMPORT]) {
            actions.loadImportRecord()
        }
    }),
])
